"""Lambda function to retrieve podcast batch results and generate audio."""

import logging
import os
from datetime import datetime
from typing import Any, Dict

import anthropic
import boto3

from .podcast_generator import (
    synthesize_speech,
    upload_to_s3,
    update_podcast_feed,
)
from .email_articles import set_last_run

logger = logging.getLogger(__name__)


def lambda_handler(event: Dict[str, Any], context: Any) -> Dict[str, Any]:  # pylint: disable=W0613
    """
    Retrieve podcast batch results, generate audio, and update RSS feed.

    Input (from event):
        {
            "batch_id": str,
            "request_counts": {...}
        }
    """
    try:
        batch_id = event["batch_id"]

        if batch_id is None:
            logger.info("No podcast batch to retrieve (no articles to process)")
            return {"status": "success", "audio_generated": False}

        # Get configuration from environment
        api_key_param = os.environ["ANTHROPIC_API_KEY_PARAMETER"]
        last_run_param = os.environ["PODCAST_LAST_RUN_PARAMETER"]
        bucket = os.environ["BUCKET"]
        distribution_id = os.environ.get("PODCAST_CLOUDFRONT_DISTRIBUTION_ID")

        # Get API key from Parameter Store
        ssm = boto3.client("ssm")
        api_key = ssm.get_parameter(Name=api_key_param, WithDecryption=True)[
            "Parameter"
        ]["Value"]

        client = anthropic.Anthropic(api_key=api_key)

        # Retrieve batch results
        script = None
        for result in client.messages.batches.results(batch_id):
            if result.result.type == "succeeded":
                script = result.result.message.content[0].text
                logger.info("Retrieved podcast script (%d characters)", len(script))
                break
            logger.error(
                "Podcast script generation failed with type %s",
                result.result.type,
            )

        if script is None:
            logger.error("Failed to retrieve podcast script from batch")
            raise RuntimeError("Failed to retrieve podcast script from batch")

        # Generate audio from script
        audio_data = synthesize_speech(script)
        if audio_data is None:
            logger.error("Failed to synthesize podcast audio")
            raise RuntimeError("Failed to synthesize podcast audio")

        # Upload to S3
        timestamp = datetime.now().strftime("%Y%m%d-%H%M%S")
        s3_key = f"podcasts/episodes/rss-digest-{timestamp}.mp3"

        upload_result = upload_to_s3(bucket, s3_key, audio_data, "audio/mpeg")
        if not upload_result:
            logger.error("Failed to upload podcast to S3")
            raise RuntimeError("Failed to upload podcast to S3")

        # Generate CloudFront URL
        cloudfront_domain_param = os.environ.get("PODCAST_CLOUDFRONT_DOMAIN_PARAMETER")
        if cloudfront_domain_param:
            cloudfront_domain = ssm.get_parameter(Name=cloudfront_domain_param)[
                "Parameter"
            ]["Value"]
            audio_url = f"https://{cloudfront_domain}/{s3_key}"
        else:
            audio_url = f"https://{bucket}.s3.amazonaws.com/{s3_key}"

        # Update podcast RSS feed
        title = f"RSS Digest - {datetime.now().strftime('%B %d, %Y')}"
        description = "Your daily digest of technology news and updates"
        pub_date = datetime.now().isoformat()

        update_result = update_podcast_feed(
            bucket=bucket,
            audio_url=audio_url,
            title=title,
            description=description,
            pub_date=pub_date,
            audio_size=len(audio_data),
            distribution_id=distribution_id,
        )

        if not update_result:
            logger.error("Failed to update podcast RSS feed")
            raise RuntimeError("Failed to update podcast RSS feed")

        # Update last_run parameter
        set_last_run(last_run_param)

        logger.info("Successfully generated and published podcast")

        return {
            "status": "success",
            "audio_generated": True,
            "audio_url": audio_url,
            "audio_size": len(audio_data),
        }

    except Exception as e:
        logger.error("Error retrieving and generating podcast: %s", e, exc_info=True)
        raise
"""Lambda function to submit podcast batch to Anthropic Message Batches API."""

import logging
import os
from datetime import UTC, datetime
from typing import Any, Dict

import anthropic
import boto3
from anthropic.types.message_create_params import MessageCreateParamsNonStreaming
from anthropic.types.messages.batch_create_params import Request

from .email_articles import get_feed_file, filter_items, get_last_run
from .models import DEFAULT_CLAUDE_MODEL
from .podcast_generator import create_podcast_script_prompt

logger = logging.getLogger(__name__)
logger.setLevel(logging.INFO)


def lambda_handler(event: Dict[str, Any], context: Any) -> Dict[str, Any]:  # pylint: disable=W0613
    """
    Submit Message Batch to Anthropic API for podcast generation.

    Returns:
        {
            "batch_id": str,
            "request_count": int,
            "submitted_at": str (ISO timestamp)
        }
    """
    try:
        # Get configuration from environment
        bucket = os.environ["RSS_BUCKET"]
        key = os.environ["RSS_KEY"]
        last_run_param = os.environ["PODCAST_LAST_RUN_PARAMETER"]
        api_key_param = os.environ["ANTHROPIC_API_KEY_PARAMETER"]
        model = os.environ.get("CLAUDE_MODEL", DEFAULT_CLAUDE_MODEL)

        # Get API key from Parameter Store
        ssm = boto3.client("ssm")
        api_key = ssm.get_parameter(Name=api_key_param, WithDecryption=True)[
            "Parameter"
        ]["Value"]

        # Retrieve and filter articles
        run_date = get_last_run(last_run_param)
        rss_file = get_feed_file(bucket, key)
        filtered_items = filter_items(rss_file, run_date)

        if not filtered_items:
            logger.info("No articles to process for podcast")
            return {
                "batch_id": None,
                "request_count": 0,
                "submitted_at": datetime.now(UTC).isoformat(),
                "articles_count": 0,
            }

        logger.info("Found %d articles to process for podcast", len(filtered_items))

        # Sort by date (newest first) and limit to 100 articles to avoid token limits
        # and ensure a manageable script length.
        filtered_items.sort(key=lambda x: x.get("sortDate", 0), reverse=True)
        processing_items = filtered_items[:100]

        if len(filtered_items) > 100:
            logger.info("Limited processing to 100 newest articles (from %d total)", len(filtered_items))

        # Create batch request (single podcast script for all articles)
        client = anthropic.Anthropic(api_key=api_key)
        prompt = create_podcast_script_prompt(processing_items)

        requests = [
            Request(
                custom_id="podcast-script",
                params=MessageCreateParamsNonStreaming(
                    model=model,
                    max_tokens=4000,  # Lower limit for podcasts to control costs
                    messages=[{"role": "user", "content": prompt}],
                ),
            )
        ]

        # Submit batch
        message_batch = client.messages.batches.create(requests=requests)

        logger.info(
            "Submitted podcast batch %s with 1 request for %d articles",
            message_batch.id,
            len(filtered_items),
        )

        # Return batch info to Step Functions
        return {
            "batch_id": message_batch.id,
            "request_count": len(requests),
            "submitted_at": datetime.now(UTC).isoformat(),
            "articles_count": len(filtered_items),
            "poll_count": 0,
        }

    except Exception as e:
        logger.error("Error submitting podcast batch: %s", e, exc_info=True)
        raise
